public class FormLayoutPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String describeAt(javax.swing.JPanel panel, int index) {
        if (index >= panel.getComponentCount()) {
            return "(missing)";
        }
        java.awt.Component c = panel.getComponent(index);
        if (c instanceof javax.swing.JLabel) {
            return "JLabel(" + ((javax.swing.JLabel) c).getText() + ")";
        }
        if (c instanceof javax.swing.JTextField) {
            return "JTextField(" + c.getName() + ")";
        }
        return c.getClass().getSimpleName();
    }

    public static void main(String[] args) {
        try {
            FormLayoutPanel panel = new FormLayoutPanel();
            java.awt.LayoutManager lm = panel.getLayout();
            String layoutDesc = (lm instanceof java.awt.GridLayout)
                    ? "GridLayout " + ((java.awt.GridLayout) lm).getRows()
                            + "x" + ((java.awt.GridLayout) lm).getColumns()
                    : String.valueOf(lm);
            check("layout manager", "GridLayout 3x2", layoutDesc);
            check("component count", 6, panel.getComponentCount());
            check("slot 0", "JLabel(Name:)", describeAt(panel, 0));
            check("slot 1", "JTextField(name)", describeAt(panel, 1));
            check("slot 2", "JLabel(Email:)", describeAt(panel, 2));
            check("slot 3", "JTextField(email)", describeAt(panel, 3));
            check("slot 4", "JLabel(Age:)", describeAt(panel, 4));
            check("slot 5", "JTextField(age)", describeAt(panel, 5));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

