import java.awt.GridLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;

public class FormLayoutPanel extends JPanel {

    private final JLabel nameLabel = new JLabel("Name:");
    private final JLabel emailLabel = new JLabel("Email:");
    private final JLabel ageLabel = new JLabel("Age:");
    private final JTextField nameField = new JTextField(10);
    private final JTextField emailField = new JTextField(10);
    private final JTextField ageField = new JTextField(10);

    public FormLayoutPanel() {
        nameField.setName("name");
        emailField.setName("email");
        ageField.setName("age");
        buildForm();
    }

    private void buildForm() {
        setLayout(new GridLayout(3, 2));
        add(nameLabel);
        add(nameField);
        add(emailLabel);
        add(emailField);
        add(ageLabel);
        add(ageField);
    }
}
